def list_files(d, max_depth=3):
    indent = "  " * d
    if max_depth < 0:
        return
    try:
        entries = os.listdir(d)
        # Sort to get files before directories
        entries.sort(key=lambda x: (os.path.isdir(os.path.join(d, x)), x[:2]))
        for e in entries:
            full = os.path.join(d, e)
            if os.path.isfile(full):
                print(f"{indent}{e}")
            else:
                # it's a dir with files - list some of them
                sub = list_files(full, max_depth-1)
                if sub is not None:
                    print(sub)
    except PermissionError as e:
        return  # Directory listing permission denied

